    test('the mktemp scratch dir is cleaned up on every exit path (EXIT trap)', function () {
        var src = file_read({ path: 'setup/dart.sh' });
        assert.ok(/trap 'rm -rf "\$\{tmp\}"' EXIT/.test(src),
            'a failed curl must not leak the ~215MB tmp dir');
    });
});

