        assert.equal(r.channel, 'beta');
        assert.ok(String(r.sdk_url).indexOf('/channels/beta/release/3.9.4/sdk/') !== -1,
            'sdk_url must pin the version on the detected channel, got: ' + r.sdk_url);
    });

