/** Run `setup/cache.sh keys dart[:<version>]` in the sandbox, return {key: <DART_CACHE_KEY>}. */
function dsCacheRun(args, opts) {
    opts = opts || {};
    var lines = ['r="$(pwd)"', 'd="$(mktemp -d)"'];
    if (opts.qualityYml !== undefined) {
        lines.push('mkdir -p "$d/.github/workflows"');
