#!/usr/bin/env bash
# Output cache paths and keys for CI platforms.
#
# Usage:
#   cache.sh keys    tool1 tool2 ...   # export {TOOL}_CACHE_PATH + {TOOL}_CACHE_KEY
#   cache.sh restore tool1 tool2 ...   # same as 'keys' (actual restore done by CI YAML)
#   cache.sh save    tool1 tool2 ...   # print paths to cache (for CI YAML reference)
#   cache.sh info                      # print cache table for all known tools
#
# Examples:
#   cache.sh keys dmtools maestro copilot node playwright
#   cache.sh keys dmtools:v1.7.195 java:17
#
# After running, CI cache steps can reference exported env vars:
#   Bitrise:  key: $DMTOOLS_CACHE_KEY   paths: $DMTOOLS_CACHE_PATH
#   GHA:      key: ${{ env.DMTOOLS_CACHE_KEY }}   path: ${{ env.DMTOOLS_CACHE_PATH }}
set -eu

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "${SCRIPT_DIR}/_common.sh"

OS_TAG="$(uname -s | tr '[:upper:]' '[:lower:]')-$(uname -m)"

# ── Per-tool cache definitions ────────────────────────────────────────────────

_cache_dmtools() {
  local version="${1:-${DMTOOLS_VERSION:-v1.7.256}}"
  export_var "DMTOOLS_CACHE_PATH" "${HOME}/.dmtools"
  export_var "DMTOOLS_CACHE_KEY"  "dmtools-${version}-${OS_TAG}"
  # Restore key uses only the minor version prefix (e.g. v1.7.) so cache
  # hits are limited to the same minor line. The install script verifies
  # the exact version and reinstalls if the patch level differs.
  local minor_prefix="${version%.*}."
  export_var "DMTOOLS_CACHE_RESTORE_KEY" "dmtools-${minor_prefix}"
}

_cache_java() {
  local version="${1:-${JAVA_VERSION:-17}}"
  # Java is managed by the OS package manager; cache JAVA_HOME only
  local home=""
  if [ "$(detect_os)" = "macos" ]; then
    home="$(/usr/libexec/java_home -v "${version}" 2>/dev/null || echo "")"
  fi
  export_var "JAVA_CACHE_PATH" "${home:-/usr/lib/jvm}"
  export_var "JAVA_CACHE_KEY"  "java-${version}-${OS_TAG}"
}

_cache_node() {
  local version="${1:-${NODE_VERSION:-20}}"
  export_var "NODE_CACHE_PATH" "${HOME}/.nvm"
  export_var "NODE_CACHE_KEY"  "nvm-node${version}-${OS_TAG}"
}

_cache_maestro() {
  local version="${1:-${MAESTRO_VERSION:-latest}}"
  export_var "MAESTRO_CACHE_PATH" "${HOME}/.maestro"
  export_var "MAESTRO_CACHE_KEY"  "maestro-${version}-${OS_TAG}"
}

_cache_copilot() {
  local version="${1:-${COPILOT_VERSION:-latest}}"
  export_var "COPILOT_CACHE_PATH" "${HOME}/.npm-global"
  export_var "COPILOT_CACHE_KEY"  "npm-global-copilot-${version}-${OS_TAG}"
}

_cache_copilot_session() {
  # shellcheck source=/dev/null
  source "${SCRIPT_DIR}/copilot-session.sh" env
}

_cache_codegraph() {
  local version="${1:-${CODEGRAPH_VERSION:-latest}}"
  # Binary cache (~/.npm-global)
  export_var "CODEGRAPH_CACHE_PATH" "${HOME}/.npm-global"
  export_var "CODEGRAPH_CACHE_KEY"  "npm-global-codegraph-${version}-${OS_TAG}"
  # Index cache (.codegraph/ in the workspace)
  local workspace="${GITHUB_WORKSPACE:-${PWD}}"
  export_var "CODEGRAPH_INDEX_CACHE_PATH" "${workspace}/.codegraph"
  export_var "CODEGRAPH_INDEX_CACHE_KEY"  "codegraph-index-${OS_TAG}"
}

_cache_playwright() {
  local version="${1:-${PLAYWRIGHT_VERSION:-latest}}"
  export_var "PLAYWRIGHT_CACHE_PATH" "${HOME}/.cache/ms-playwright"
  export_var "PLAYWRIGHT_CACHE_KEY"  "playwright-browsers-${version}-${OS_TAG}"
}

_cache_codemie() {
  local version="${1:-${CODEMIE_VERSION:-latest}}"
  export_var "CODEMIE_CACHE_PATH" "${HOME}/.local/bin"
  export_var "CODEMIE_CACHE_KEY"  "codemie-${version}-${OS_TAG}"
}

_cache_kimi() {
  local version="${1:-${KIMI_VERSION:-latest}}"
  export_var "KIMI_CACHE_PATH" "${HOME}/.kimi-code"
  export_var "KIMI_CACHE_KEY"  "kimi-${version}-${OS_TAG}"
}

_cache_cursor() {
  export_var "CURSOR_CACHE_PATH" "${HOME}/.cursor"
  export_var "CURSOR_CACHE_KEY"  "cursor-${OS_TAG}"
}

_cache_kimi_session() {
  # shellcheck source=/dev/null
  source "${SCRIPT_DIR}/kimi-session.sh" env
}

_cache_cursor_session() {
  # shellcheck source=/dev/null
  source "${SCRIPT_DIR}/cursor-session.sh" env
}

_cache_fa_session() {
  source "${SCRIPT_DIR}/fa-session.sh" env
}

_cache_gradle() {
  # Gradle wrapper distribution (~/.gradle/wrapper) and dependency cache (~/.gradle/caches).
  # Keys hash the files most likely to change the cache content:
  #   wrapper key  — gradle-wrapper.properties (changes when Gradle version bumps)
  #   caches key   — libs.versions.toml + all *.gradle.kts (changes when deps or build scripts change)
  local workspace="${GITHUB_WORKSPACE:-${PWD}}"

  local wrapper_hash
  wrapper_hash="$(hash_file "${workspace}/gradle/wrapper/gradle-wrapper.properties")"

  # Aggregate hash over the version catalog + every Gradle Kotlin build script,
  # sorted for stability across filesystems/find implementations.
  local caches_hash="nokey"
  if command -v find &>/dev/null; then
    local build_files
    build_files="$(find "${workspace}" \( -name "libs.versions.toml" -o -name "*.gradle.kts" \) -not -path "*/build/*" -not -path "*/.git/*" 2>/dev/null | sort)"
    if [ -n "${build_files}" ]; then
      # shellcheck disable=SC2086
      caches_hash="$(hash_files ${build_files})"
    fi
  fi

  export_var "GRADLE_WRAPPER_CACHE_PATH" "${HOME}/.gradle/wrapper"
  export_var "GRADLE_WRAPPER_CACHE_KEY"  "gradle-wrapper-${wrapper_hash}"
  export_var "GRADLE_WRAPPER_CACHE_RESTORE_KEY" "gradle-wrapper-"

  export_var "GRADLE_CACHES_CACHE_PATH" "${HOME}/.gradle/caches"
  export_var "GRADLE_CACHES_CACHE_KEY"  "gradle-caches-${caches_hash}"
  export_var "GRADLE_CACHES_CACHE_RESTORE_KEY" "gradle-caches-"
}

_cache_konan() {
  # Kotlin/KMP native toolchain (~/.konan).
  # Key hashes libs.versions.toml because the Kotlin version bump triggers a new toolchain download.
  local workspace="${GITHUB_WORKSPACE:-${PWD}}"
  local konan_hash
  konan_hash="$(hash_file "${workspace}/gradle/libs.versions.toml")"

  export_var "KONAN_CACHE_PATH" "${HOME}/.konan"
  export_var "KONAN_CACHE_KEY"  "konan-${konan_hash}"
  export_var "KONAN_CACHE_RESTORE_KEY" "konan-"
}

_cache_dart() {
  # Dart SDK (gh-918: factory legs on dart repos need the same gate toolchain
  # as CI — setup/dart.sh resolves the channel/version and installs under
  # ~/.dart-sdk/dart-sdk). Key on the requested channel/version; the restore
  # key keeps any previously cached SDK until the channel moves.
  local version="${1:-${DART_VERSION:-stable}}"
  export_var "DART_CACHE_PATH" "${HOME}/.dart-sdk"
  export_var "DART_CACHE_KEY"  "dart-${version}-${OS_TAG}"
  export_var "DART_CACHE_RESTORE_KEY" "dart-"
}

_cache_android() {
  local compile_sdk="${1:-${ANDROID_COMPILE_SDK:-36}}"
  # Android SDK packages are large but stable — key on compileSdk version.
  local android_home="${ANDROID_HOME:-${HOME}/Android/Sdk}"

  export_var "ANDROID_CACHE_PATH" "${android_home}/platforms/android-${compile_sdk} ${android_home}/build-tools ${android_home}/platform-tools"
  export_var "ANDROID_CACHE_KEY"  "android-sdk-${compile_sdk}-${OS_TAG}"
  export_var "ANDROID_CACHE_RESTORE_KEY" "android-sdk-${compile_sdk}-"
}

# ── Dispatch ──────────────────────────────────────────────────────────────────

_dispatch_tool() {
  local tool="$1" version="$2"
  case "${tool}" in
    dmtools)  _cache_dmtools  "${version}" ;;
    java)     _cache_java     "${version}" ;;
    node)     _cache_node     "${version}" ;;
    maestro)  _cache_maestro  "${version}" ;;
    copilot)  _cache_copilot  "${version}" ;;
    copilot-session) _cache_copilot_session ;;
    kimi-session) _cache_kimi_session ;;
    cursor-session) _cache_cursor_session ;;

    fa-session) _cache_fa_session ;;
    codegraph) _cache_codegraph "${version}" ;;
    playwright) _cache_playwright "${version}" ;;
    codemie)  _cache_codemie  "${version}" ;;
    kimi)     _cache_kimi     "${version}" ;;
    cursor)   _cache_cursor ;;
    gradle)   _cache_gradle ;;
    konan)    _cache_konan ;;
    dart)     _cache_dart  "${version}" ;;
    android)  _cache_android  "${version}" ;;
    *)        echo "⚠️  Unknown tool '${tool}' — skipping cache config" ;;
  esac
}

_print_info() {
  echo ""
  echo "┌─────────────┬──────────────────────────────────┬────────────────────────────────────────────────┐"
  printf "│ %-11s │ %-32s │ %-46s │\n" "Tool" "Cache Path" "Cache…

/**
 * Unit tests for setup/dart.sh — the cached, channel-aware Dart SDK
 * provisioner for machine-factory leg sessions (gh-918).
 *
 * The factory legs on Dart repos had NO dart SDK: rework legs could not run
 * `dart analyze/test/format` or `crap4dart check`, so they could neither see
 * nor verify quality-gate violations and claimed success while violations
 * stayed in place (gh-918 evidence: #408 operator-fixed CRAP 9.00, #413
 * rework "success" with method_size violations left in place, #414 operator
 * refactor). setup/dart.sh is the fix: same pattern as the golden-test
 * Flutter toolchain for fa legs — cached per resolved version, exposed on
 * PATH for the leg session, resolving the SAME channel/version the checked
 * out repo's quality workflow (dart-lang/setup-dart step) uses.
 *
 * The canonical green gate (agent-pack-release.yml) sets
 * CLI_ALLOWED_COMMANDS=bash so cli_execute_command may run the real bash
 * script against hermetic mktemp sandboxes (no worktree pollution). Where
 * bash is not executable the suite self-skips — the degraded-harness
 * precedent of test_reviewVerdict.js.
 *
 * Coverage (network-free decision logic — `plan`/`status` subcommands):
 *   - channel/version resolution precedence: argument > DART_VERSION env >
 *     quality-workflow dart-lang/setup-dart detection > stable default;
 *   - quality.yml `sdk:` pin + `channel:` pair → version mode on that
 *     channel (exactly "same channel the repo's quality.yml uses");
 *   - dart-archive URL/paths shape (os/arch mapping, dart-sdk/bin layout);
 *   - installed-version parsing from the `dart --version` banner;
 *   - wiring contracts: install.sh ALL_TOOLS + verify mapping, cache.sh
 *     DART_CACHE_* entries (mirrors test_packLaunchContract.js style).
 *
 * Uses: cli_execute_command, file_read, test(), suite(), assert
 */

// ── Capability probe ─────────────────────────────────────────────────────────

var _dsCanRun_ = typeof cli_execute_command === 'function';
if (_dsCanRun_) {
    try {
        cli_execute_command({ command: 'bash -c "echo __ds_probe__"' });
    } catch (e) {
        _dsCanRun_ = false; // bash not whitelisted in this dmtools env
    }
}

// ── Helpers ──────────────────────────────────────────────────────────────────

/** Shell-single-quote a value (safe inside `bash -c '…'` after one wrap). */
function dsShq(v) {
    return "'" + String(v).replace(/'/g, "'\\''") + "'";
}

/** Parse the script's key=value output into an object. */
function dsParseKv(out) {
    var res = {};
    String(out).split('\n').forEach(function (line) {
        line = line.replace(/\r$/, '');
        var i = line.indexOf('=');
        if (i === -1) return;
        res[line.substring(0, i).trim()] = line.substring(i + 1).trim();
    });
    return res;
}

/** os/arch pair the script should resolve on THIS machine (for URL asserts). */
function dsOsArch() {
    var lines = [
        'case "$(uname -s)" in Darwin) echo macos;; Linux) echo linux;; *) echo unknown;; esac',
        'case "$(uname -m)" in arm64|aarch64) echo arm64;; *) echo x64;; esac'
    ];
    var out = cli_execute_command({ command: 'bash -c ' + dsShq(lines.join('; ')) });
    var parts = String(out).trim().split('\n');
    return { os: parts[0], arch: parts[1] };
}

/**
 * Run `setup/dart.sh <subcommand>` inside a fresh mktemp sandbox.
 * opts: qualityYml — contents written to <sandbox>/.github/workflows/quality.yml
 *       env        — extra `KEY=value` strings prefixed to the invocation
 *       stubDart   — version banner a fake `dart` on PATH prints (status tests)
 */
function dsRun(subcommand, opts) {
    opts = opts || {};
    var lines = ['r="$(pwd)"', 'd="$(mktemp -d)"'];
    if (opts.qualityYml !== undefined) {
        lines.push('mkdir -p "$d/.github/workflows"');
        lines.push('printf %s ' + dsShq(opts.qualityYml) + ' > "$d/.github/workflows/quality.yml"');
    }
    if (opts.stubDart !== undefined) {
        lines.push('mkdir -p "$d/bin"');
        // The banner is quoted INSIDE the stub script (dsShq(opts.stubDart) rides
        // inside the script text, not as a shell argument) — an unquoted echo
        // would die on the banner's parentheses and print no version at all.
        lines.push('printf %s ' + dsShq('#!/bin/sh\necho ' + dsShq(opts.stubDart)) + ' > "$d/bin/dart"');
        lines.push('chmod +x "$d/bin/dart"');
    }
    var env = (opts.env || []).slice();
    // Hermetic against the HOST: the script's installed-version probe falls
    // back to <DART_INSTALL_DIR>/dart-sdk/bin/dart, so a real SDK cached on
    // the runner (or left by a manual install — live: the verification step
    // of this very ticket) would leak into `status`/`plan`. Point the
    // install dir INSIDE the sandbox for every invocation.
    env.push('DART_INSTALL_DIR="$d/nodart"');
    if (opts.stubDart !== undefined) {
        env.push('PATH="$d/bin:$PATH"');
    }
    lines.push('cd "$d"');
    lines.push((env.length ? env.join(' ') + ' ' : '') +
        'bash "$r/setup/dart.sh" ' + subcommand);
    lines.push('rc=$?; cd /; rm -rf "$d"; exit $rc');
    return dsParseKv(cli_execute_command({ command: 'bash -c ' + dsShq(lines.join('\n')) }));
}

// Fixture: a minimal quality workflow using dart-lang/setup-dart (beta channel).
var DS_QUALITY_BETA = [
    'name: Quality',
    'on: [push]',
    'jobs:',
    '  gate:',
    '    runs-on: ubuntu-latest',
    '    steps:',
    '      - uses: actions/checkout@v4',
    '      - uses: dart-lang/setup-dart@v1',
    '        with:',
    '          channel: beta',
    '      - run: dart analyze'
].join('\n');

// Fixture: quality workflow pinning BOTH an sdk version and a channel.
var DS_QUALITY_PINNED = DS_QUALITY_BETA
    .replace('          channel: beta', '          channel: beta\n          sdk: 3.9.4');

// ── Suite ────────────────────────────────────────────────────────────────────

suite('setup/dart.sh: target resolution precedence (gh-918)', function () {

    if (!_dsCanRun_) {
        console.log(
            '  ⏭️  skipped — bash not executable here (node-harness mock gap; ' +
            'the canonical gate runs this suite via CLI_ALLOWED_COMMANDS=bash)');
        return;
    }

    test('no argument, no quality workflow → stable default, source=default', function () {
        var r = dsRun('plan');
        assert.equal(r.mode, 'channel');
        assert.equal(r.channel, 'stable');
        assert.equal(r.requested, 'stable');
        assert.equal(r.source, 'default');
