suite('setup/dart.sh: ~215MB download hardening', function () {
    test('the main SDK download gets connect-timeout + retries (a stalled transfer must not hang the leg)', function () {
        var src = file_read({ path: 'setup/dart.sh' });
        assert.ok(/curl -fsSL --connect-timeout 30 --retry 3 --retry-delay 5 "\$\{url\}"/.test(src),
            'main download must use --connect-timeout/--retry/--retry-delay, not a bare curl');
    });

    test('the downloaded archive is verified against the dart-archive .sha256 sidecar before extraction', function () {
        var src = file_read({ path: 'setup/dart.sh' });
        assert.ok(/\.sha256/.test(src) && /sha256sum|shasum/.test(src),
            'dart.sh must fetch and verify the .sha256 sidecar');
        assert.ok(/verify_sha256 "\$\{tmp\}\/dartsdk\.zip" "\$\{url\}\.sha256"/.test(src),
            'do_install must verify the archive BEFORE extraction');
    });

    test('the mktemp scratch dir is cleaned up on every exit path (EXIT trap)', function () {
        var src = file_read({ path: 'setup/dart.sh' });
        assert.ok(/trap 'rm -rf "\$\{tmp\}"' EXIT/.test(src), 'curl failure must not leak the ~215MB tmp dir');
    });
